#!/usr/bin/env python3
"""Temporary branch bootstrap for two large generated M1 files."""
from __future__ import annotations
import base64
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAYLOADS = {
    "src/mapel_linkage/configuration/models.py": "",
    "schemas/linkage-config.schema.json": "",
}

for relative, encoded in PAYLOADS.items():
    target = ROOT / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(zlib.decompress(base64.b64decode(encoded)))

print("M1 large files assembled.")
